<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;700;900&display=swap" rel="stylesheet">
<style>
  *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

  html { font-size: 16px; }

  body {
    font-family: 'Inter', Arial, Helvetica, sans-serif;
    background: #FFFFFF;
    color: #111111;
    min-height: 100vh;
    overflow-x: hidden;
  }

  /* ── Mondrian grid container ─────────────────────────── */
  .grid {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    grid-template-rows: auto auto auto;
    gap: 0;
    min-height: 100vh;
    border: 12px solid #111111;
  }

  /* ── Colour blocks ───────────────────────────────────── */
  .block-red   { background: #E3000F; }
  .block-blue  { background: #003DA5; }
  .block-yellow{ background: #FCD116; }
  .block-white { background: #FFFFFF; }
  .block-grey  { background: #C8C8C8; }

  /* ── Header banner ───────────────────────────────────── */
  .header {
    grid-column: 1 / -1;
    padding: 2.5rem 3rem 2rem;
    border-bottom: 12px solid #111111;
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 1rem;
  }
  .header h1 {
    font-weight: 900;
    font-size: clamp(1.4rem, 3vw, 2.2rem);
    letter-spacing: -0.02em;
    line-height: 1.15;
  }
  .header .meta {
    font-weight: 700;
    font-size: 0.95rem;
    color: #555;
  }

  /* ── Main image block ────────────────────────────────── */
  .painting {
    grid-column: 1 / 2;
    grid-row: 2 / 4;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 2rem;
    border-right: 12px solid #111111;
  }
  .painting-frame {
    width: 100%;
    max-width: 360px;
    aspect-ratio: 3 / 4;
    border: 8px solid #111111;
    position: relative;
    overflow: hidden;
    background: #FFFFFF;
  }
  /* Abstract Mondrian-style SVG inside the frame */
  .painting-frame svg {
    width: 100%;
    height: 100%;
    display: block;
  }

  /* ── Content columns ─────────────────────────────────── */
  .content {
    grid-column: 2 / 4;
    grid-row: 2 / 4;
    padding: 2.5rem 3rem;
    display: flex;
    flex-direction: column;
    gap: 2rem;
    overflow-y: auto;
  }

  .content h2 {
    font-weight: 900;
    font-size: 1.3rem;
    letter-spacing: -0.01em;
    border-bottom: 4px solid #111111;
    padding-bottom: 0.4rem;
  }

  .content p, .content li {
    font-size: 0.95rem;
    line-height: 1.65;
    color: #222;
  }

  .content ul {
    list-style: none;
    padding-left: 0;
  }
  .content ul li {
    padding: 0.3rem 0;
    padding-left: 1.2rem;
    position: relative;
  }
  .content ul li::before {
    content: '';
    position: absolute;
    left: 0;
    top: 0.75rem;
    width: 0.55rem;
    height: 0.55rem;
    background: #111111;
  }

  .highlight {
    background: #FCD116;
    padding: 0.15rem 0.35rem;
    font-weight: 700;
  }

  /* ── CTA strip ───────────────────────────────────────── */
  .cta {
    margin-top: auto;
    padding: 1.2rem 1.5rem;
    border: 4px solid #111111;
    display: flex;
    align-items: center;
    gap: 1rem;
    flex-wrap: wrap;
  }
  .cta p {
    font-size: 0.9rem;
    font-weight: 700;
    flex: 1 1 auto;
  }
